pragma solidity ^0.8.24;

// ============================================================================
// WARNING: GENESIS SEEDING HELPER — TEMPORARY, NEVER DEPLOYED ON THE REAL CHAIN
//
// This is the TEMPORARY counterpart of: contracts/ValidatorsRegistry.sol
//
// ✅ FIXED (critical bug found in review): this file had fallen out of sync with the real
// contract in two ways that would have corrupted genesis storage if used as-is:
//   1. The ValidatorInfo struct here was missing the `isPaidEntrant` field added later to the
//      real contract.
//   2. The real contract now declares TWO scalar variables (`paidValidatorCount`, `verifier`)
//      BETWEEN `validators` and `activeValidators`/`activeIndex` — but this helper previously
//      declared `activeValidators`/`activeIndex` immediately after `validators`, with nothing
//      in between. Since a `mapping` or dynamic `array` type occupies exactly one storage slot
//      for its own "base" (the actual entries live at computed keccak256 offsets from that
//      base), every variable declared AFTER the mapping/array shifts by exactly one slot for
//      each scalar inserted before it. Without the two placeholder declarations below in the
//      SAME relative position, this helper's computed slot for `activeValidators.length` would
//      have been off by 2 relative to the real contract — meaning naively copying "helper slot
//      N → real contract slot N" would have written the founding validator *array* data into
//      what the real contract reads as `paidValidatorCount`/`verifier`, and vice versa.
//
// Purpose: the real ValidatorsRegistry.sol has no constructor (it is injected directly into the
// genesis alloc). But `validators` (a mapping to a struct), `activeValidators` (a dynamic
// array), and `activeIndex` (a mapping) cannot be populated with any contract-level Solidity
// syntax. This helper contract implements that exact seeding logic inside a real, NO-ARGUMENT
// constructor — the genesis timestamp and initial validator addresses are hardcoded directly
// below, not passed in as constructor arguments — so that running it once on a temporary local
// chain (Anvil/Hardhat) lets the EVM itself perform the keccak256 storage-slot math required for
// each mapping/array entry.
//
// How the genesis-building tool should use this file:
//   1. 🔶 FILL_IN: replace the placeholder genesis timestamp and every placeholder validator
//      address below with the real, final values before deploying this file anywhere. The
//      NUMBER OF ENTRIES in the array (currently 7, matching the real founding validator count)
//      must also be adjusted if that count ever changes — add or remove array entries as
//      needed, updating every place the array length is written (the type declaration and the
//      literal list itself).
//   2. Deploy this file (no constructor arguments) on a temporary local chain.
//   3. Extract its full final storage (via eth_getStorageAt for every touched slot, or a
//      state-dump tool).
//   4. Write that storage — together with the REAL ValidatorsRegistry.sol's compiled runtime
//      bytecode (NOT this file's bytecode) — under address 0x3333...3333 in genesis.json's
//      `alloc` section. ⚠️ The `paidValidatorCount` and `verifier` placeholder slots below will
//      extract as 0 / address(0) from THIS helper (their constructor never touches them) — do
//      NOT copy those two specific slots verbatim from the helper. `paidValidatorCount` should
//      genuinely be left at 0 (founders don't count toward the paid curve — see the real
//      contract's own doc comment), which needs no action at all (0 is Solidity's storage
//      default, so simply omitting that slot from the genesis alloc write already gives the
//      correct result). `verifier` must instead be set to its real, final operational-key
//      address directly in the genesis alloc at its own slot (immediately after
//      `paidValidatorCount`'s slot) — exactly like every other simple scalar (entryThresholdBase,
//      growthFactorPerValidator, membershipFeeBps, and the rest), none of which need this
//      helper either, per the real contract's own "GENESIS FILL-IN" comment.
//
// WARNING: the field order and types below must exactly match the real ValidatorsRegistry.sol,
// or the extracted storage slots will not line up with the final contract. Whenever the real
// ValidatorsRegistry.sol changes, this file must be manually kept in sync.
// ============================================================================
contract ValidatorsRegistry_GenesisSeed {
    // --- Exact copy of the real ValidatorsRegistry.sol, up to the point where mappings/arrays start ---
    enum Status { None, Probation, Active, Demoted, Exiting }

    struct ValidatorInfo {
        Status status;
        uint256 lockedStake;
        uint256 periodStartedAt;
        // ✅ CHANGED (off-chain verification architecture redesign): the packed liveness field
        // that used to live here was removed entirely from the real ValidatorsRegistry.sol —
        // liveness is checked off-chain now, with only status-change decisions (and their
        // evidence hashes) recorded on-chain, in a SEPARATE mapping (statusDecisions) that
        // genesis does not need to seed for founding validators (they start with none). This
        // struct must keep matching the real one's field count and order exactly, or every
        // subsequent mapping-entry slot computation breaks — see isPaidEntrant's comment below.
        uint256 pendingSlashEpoch;
        uint256 demotedAt;
        bool isPaidEntrant; // ✅ ADDED — must match the real struct exactly, or the per-entry
        // struct size (and therefore every subsequent mapping-entry slot computation) would be
        // wrong even for the `validators` mapping itself, not just the scalars after it.
    }

    mapping(address => ValidatorInfo) public validators;

    // ✅ ADDED — placeholder ONLY, to reserve the correct relative slot position (see the
    // warning above). This helper's constructor deliberately never writes to it — it must stay
    // at its Solidity storage default (0), which is exactly the correct genesis value for
    // founding validators (see the real contract's own doc comment on this field).
    uint256 public paidValidatorCount;

    // ✅ ADDED — placeholder ONLY, same reasoning as paidValidatorCount above. The real
    // verifier address is set directly in the genesis alloc at this slot, NOT via this helper —
    // this declaration exists purely to occupy the correct slot position so that
    // `activeValidators`/`activeIndex` below land where the real contract expects them.
    address public verifier;

    address[] private activeValidators;
    mapping(address => uint256) private activeIndex;

    // ✅ FIXED (found in independent review — a real bug, not just documentation): 14 economic/
    // timing parameters (entryThresholdBase, growthFactorPerValidator, ..., paramProposalCount)
    // and the `massFailureChecked` mapping sit between `activeIndex` and `everActivated` in the
    // real contract (slots 5–19) — this gap reserves that exact span, purely to occupy the
    // correct slot position, so `everActivated` below lands at the real contract's slot 20. Their
    // actual values are set by genesis overlay (perPaymentCap-style), not by this constructor.
    uint256[15] private __gap1;

    // ✅ FIXED (independent review): without this, founders would be genesis-injected as `Active`
    // (see the constructor below) but with `everActivated == false` — the exact state
    // `BlockRewardDistributor` now rejects with "address was never a legitimate validator" (see
    // ValidatorsRegistry.sol's own doc comment on this field). The constructor below DOES write to
    // this one, unlike the placeholders above — every founder must get `true` here, or the very
    // first real `distributeRewards()` call reverts the moment it tries to pay a founder.
    mapping(address => bool) public everActivated;
    // L04: slots 21–35 of the real contract (fields declared after everActivated, up to paramProposalCount) — placeholder only.
    // statusNonce (slot 36) stays 0 at genesis; every founder gets the checkpoint {nonce: 0, active: true} in activeCheckpoints
    // (slot 37), so wasActiveAt(founder, n) is true for every proposal created before the founder's first status change.
    uint256[15] private __gap2;
    struct ActiveCheckpoint {
        uint64 nonce;
        bool active;
    }
    uint256 public statusNonce;
    mapping(address => ActiveCheckpoint[]) private activeCheckpoints;

    // ------------------------------------------------------------------
    // No-argument constructor — the genesis timestamp and initial validator set are hardcoded
    // directly below.
    // 🔶 FILL_IN: replace the placeholder timestamp (0) and every 0x000...000 address with the
    // real, final, agreed-upon founding validator set before this file is ever deployed
    // anywhere.
    // ------------------------------------------------------------------
    constructor() {
        uint256 genesisTimestamp = 0; // 🔶 FILL_IN — the real genesis timestamp of the live network

        address[7] memory initialValidators = [
            address(0), // Alireza Zojaji
            address(0), // Citex Corp. 1
            address(0), // Citex Corp. 2
            address(0), // Mahkameh Sharifzad
            address(0), // Mostafa Naghipoorfar
            address(0), // Sepehr Mohammadi
            address(0) // Siavash Tafazzoli
        ];

        for (uint256 i = 0; i < initialValidators.length; i++) {
            address v = initialValidators[i];
            require(v != address(0), "GenesisSeed: zero address - fill in real values first");
            require(validators[v].status == Status.None, "GenesisSeed: duplicate initial validator");

            validators[v] = ValidatorInfo({
                status: Status.Active,
                lockedStake: 0,
                periodStartedAt: genesisTimestamp,
                pendingSlashEpoch: 0,
                demotedAt: 0,
                isPaidEntrant: false // founders are always free, never paid entrants
            });
            activeIndex[v] = activeValidators.length + 1;
            activeValidators.push(v);
            everActivated[v] = true; // ✅ FIXED — see the doc comment on this field's declaration above
            activeCheckpoints[v].push(ActiveCheckpoint({nonce: 0, active: true})); // L04
        }
        // paidValidatorCount and verifier are deliberately left untouched — see the doc
        // comments on their declarations above.
    }

    // Convenience view for manual inspection during testing — plays no role in storage
    // extraction itself.
    function getActiveValidators() external view returns (address[] memory) {
        return activeValidators;
    }
}

contracts-baseline/IdentityRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./SurAddresses.sol";

/// @title IdentityRegistry
/// @notice Sur's sixth structural contract (fixed address `0x6666...6666`) — the single source
///         of truth for identity across **all network users**, not just validators. Inspired by
///         the project's earlier standards SIP001/SIP002 ("Identity verification method for
///         individual and legal-entity users" and "Use of identity verification services by
///         dApps"), with two deliberate changes from the original:
///
///         1. **No notary office.** SIP001 required an in-person notarized signature. Here it is
///            replaced with a fully online process: eKYC verification (face matching + liveness
///            detection + document authenticity check, performed by a licensed provider) +
///            digitally signing a challenge with the user's own Sur key (this second step is
///            exactly SIP001's original idea, unchanged).
///
///         2. **No sensitive raw data on-chain.** SIP001 proposed storing national ID / name /
///            birth-certificate data in a "confidential smart contract." This is not technically
///            possible: no storage on a public blockchain is ever truly confidential
///            (`eth_getStorageAt` is always available), and for low-entropy data such as a
///            10-digit national ID, even hashing provides no real protection without a secret
///            salt. Solution: raw data never enters this contract; only a verification status
///            (bool) and a commitment (kept solely to prove non-tampering in a possible future
///            legal dispute, never used to answer a query) live on-chain. The "matching"
///            operation itself (SIP002 section 6) must be an off-chain API call, never an
///            on-chain transaction — because even if the contract never reveals the answer, the
///            **transaction's own input parameter** (the value being compared against) is
///            always visible in public calldata. Full details in
///            `sur-identity-registry-spec.md`.
contract IdentityRegistry {
    // ------------------------------------------------------------------
    // Fixed cross-contract address (see SurAddresses.sol)
    // ------------------------------------------------------------------
    address public constant FOUNDATION = SurAddresses.FOUNDATION_DAO;

    // ------------------------------------------------------------------
    // Self-attested identity (SIP001's first layer) — unchanged from our earlier design, just
    // relocated out of ValidatorsRegistry.
    // ------------------------------------------------------------------
    enum PersonType { Individual, Legal }

    struct Identity {
        bool registered;
        PersonType personType;
        string name;
        bool phoneVerified;      // the actual phone number is never stored here — only this flag
        bool telegramVerified;   // the actual Telegram ID is never stored here — only this flag
        bool kycVerified;        // new — result of full eKYC (photo + national ID + face match)
        bytes32 kycCommitment;   // new — kept only to prove non-tampering in disputes, never for matching
        address migratedTo;      // new — non-zero means this address is "burned" and its identity has been migrated to a new address (see spec section 3.4; equivalent to SIP001 sections 7/8)
    }

    mapping(address => Identity) public identities;

    // ------------------------------------------------------------------
    // Operational key — controlled by the Foundation (not the validators' board), because
    // identity verification is the Foundation's responsibility, per SIP001's original design
    // ("the Sur Foundation is responsible for recording verified information about individuals
    // and legal entities").
    // ------------------------------------------------------------------

    event IdentityRegistered(address indexed who, PersonType personType, string name);
    event PhoneVerificationUpdated(address indexed who, bool verified);
    event TelegramVerificationUpdated(address indexed who, bool verified);
    event KycVerificationUpdated(address indexed who, bool verified, bytes32 commitment);
    event IdentityMigrated(address indexed oldAddress, address indexed newAddress);
    event IdentityOracleUpdated(address indexed oldOracle, address indexed newOracle);

    modifier onlyFoundation() {
        require(msg.sender == FOUNDATION, "IdentityRegistry: caller is not the Foundation");
        _;
    }

    modifier onlyIdentityOracle() {
        require(msg.sender == identityOracle, "IdentityRegistry: caller is not the identity oracle");
        _;
    }

    // ------------------------------------------------------------------
    // 🔶 GENESIS FILL-IN — this contract has no constructor because it is injected directly
    // into the genesis `alloc` (its constructor would never execute on the real chain). The
    // off-chain genesis-building tool must simulate this contract's deployment (with the real
    // constructor argument, on a temporary local chain) and copy the resulting storage into the
    // final genesis file — do NOT just deploy this exact source as-is expecting the placeholder
    // below to matter on-chain; it exists purely as a documentation/tooling marker.
    // ------------------------------------------------------------------

    /// @dev ✅ FILLED: initial identityOracle address, read from SurAddresses.sol (single
    ///      source of truth for all four oracle addresses — see that file for rationale).
    address public identityOracle = SurAddresses.IDENTITY_ORACLE;

    // ------------------------------------------------------------------
    // Self-attestation — any address, not just validators
    // ------------------------------------------------------------------

    /// @notice Registers/updates self-attested identity (name and person type only). Callable
    ///         by any address, at any time; calling it again never resets any verification flag.
    function registerIdentity(PersonType personType, string calldata name) external {
        require(bytes(name).length > 0, "IdentityRegistry: empty name");

        Identity storage id_ = identities[msg.sender];
        id_.registered = true;
        id_.personType = personType;
        id_.name = name;

        emit IdentityRegistered(msg.sender, personType, name);
    }

    /// @notice Tier-zero check (open access, no dApp registration required) — exactly equivalent
    ///         to SIP002 section 6-1: "has this address registered an identity at all?", without
    ///         revealing any other data. Migrated addresses (`migratedTo != 0`) no longer return
    ///         `true` — see spec section 3.4.
    function hasIdentity(address who) external view returns (bool) {
        Identity storage id_ = identities[who];
        return id_.registered && id_.migratedTo == address(0);
    }

    /// @notice Public verification-status check — everything here is boolean, no raw data, so
    ///         freely disclosing it is not a problem (exactly like SIP002 section 6-1).
    function getVerificationStatus(address who)
        external
        view
        returns (bool registered, bool phoneVerified, bool telegramVerified, bool kycVerified)
    {
        Identity storage id_ = identities[who];
        return (id_.registered, id_.phoneVerified, id_.telegramVerified, id_.kycVerified);
    }

    // ------------------------------------------------------------------
    // Verification — identityOracle only (off-chain Identity Service; see
    // sur-identity-registry-spec.md for details)
    // ------------------------------------------------------------------

    function setPhoneVerified(address who, bool verified) external onlyIdentityOracle {
        identities[who].phoneVerified = verified;
        emit PhoneVerificationUpdated(who, verified);
    }

    function setTelegramVerified(address who, bool verified) external onlyIdentityOracle {
        identities[who].telegramVerified = verified;
        emit TelegramVerificationUpdated(who, verified);
    }

    /// @notice Records the result of a full eKYC check (personal photo + national ID card +
    ///         birth-certificate-level details + face match). `commitment` is a salted hash of
    ///         the full verified data set — kept **only** to prove non-tampering in a possible
    ///         future legal dispute; no on-chain function ever uses it to answer a "matching"
    ///         query (that operation always goes through the off-chain Identity Service API —
    ///         see section 5 of `sur-identity-registry-spec.md`).
    function setKycVerified(address who, bool verified, bytes32 commitment) external onlyIdentityOracle {
        Identity storage id_ = identities[who];
        id_.kycVerified = verified;
        id_.kycCommitment = verified ? commitment : bytes32(0);
        emit KycVerificationUpdated(who, verified, id_.kycCommitment);
    }

    // ------------------------------------------------------------------
    // Identity recovery — the online replacement for SIP001 sections 7/8 (lost key / burned
    // address). Calling this function must always follow an independent off-chain verification
    // process (see spec section 3.4): for phone/Telegram-only users, repeating the OTP flow is
    // enough; for KYC-verified users, the eKYC provider must confirm the new selfie matches the
    // previously stored biometric data for the same national ID — this is a recovery, not a
    // fresh registration.
    // ------------------------------------------------------------------

    /// @notice Migrates the full identity status from an old (lost/compromised) address to a new
    ///         one. The old address is permanently "burned" (`hasIdentity` no longer returns true
    ///         for it), but its record — and its liability for past actions — is not erased, it
    ///         simply can no longer be used.
    function migrateIdentity(address oldAddr, address newAddr) external onlyIdentityOracle {
        require(newAddr != address(0), "IdentityRegistry: zero new address");
        Identity storage oldId = identities[oldAddr];
        require(oldId.registered, "IdentityRegistry: old address has no identity");
        require(oldId.migratedTo == address(0), "IdentityRegistry: old address already migrated");

        Identity storage newId = identities[newAddr];
        newId.registered = true;
        newId.personType = oldId.personType;
        newId.name = oldId.name;
        newId.phoneVerified = oldId.phoneVerified;
        newId.telegramVerified = oldId.telegramVerified;
        newId.kycVerified = oldId.kycVerified;
        newId.kycCommitment = oldId.kycCommitment;

        oldId.migratedTo = newAddr;

        emit IdentityMigrated(oldAddr, newAddr);
    }

    // ------------------------------------------------------------------
    // Key rotation — Foundation only (not the validators' board)
    // ------------------------------------------------------------------
    function setIdentityOracle(address newOracle) external onlyFoundation {
        require(newOracle != address(0), "IdentityRegistry: zero oracle address");
        emit IdentityOracleUpdated(identityOracle, newOracle);
        identityOracle = newOracle;
    }
}

contracts-baseline/reference-dapps/SurZe.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

// ============================================================================
// ⚠️⚠️⚠️  REFERENCE / PROPOSAL CONTRACT — NOT PRODUCTION-READY  ⚠️⚠️⚠️
//
// This is a REFERENCE DAPP, not one of Sur's six structural genesis contracts. It is not
// genesis-injected, has a normal constructor, and is deployed like any ordinary dApp — by the
// Foundation or by any independent developer, at any time.
//
// Full design rationale, phased rollout plan, and known risks are documented in
// sur-zether-confidential-transfers-proposal.md — read that document first.
//
// WHAT IS SAFE TO USE DIRECTLY FROM THIS FILE:
//   - The encrypted-balance storage layout (struct Ciphertext / Account).
//   - The elliptic-curve homomorphic arithmetic (_ecAdd / _ecMul), which calls Ethereum's
//     standard ecAdd (0x06) / ecMul (0x07) precompiles — precompiles present on every
//     standard EVM client, including Besu, without any client modification.
//   - The overall contract flow (register → fund → transfer → burn).
//
// WHAT IS **NOT** SAFE TO USE DIRECTLY — MUST BE REPLACED BEFORE ANY REAL DEPLOYMENT:
//   - `IZetherVerifier` is an ILLUSTRATIVE interface. It shows the SHAPE of what a Zether
//     zero-knowledge proof verifier needs to check, but its exact parameters have NOT been
//     validated against any specific published Zether reference implementation. The actual
//     verifier contract implementing this interface (Σ-Bullets / Bulletproofs verification)
//     MUST be forked from an audited, published, well-reviewed Zether implementation — never
//     written from scratch without a formal cryptography review. A subtle bug in this layer
//     can allow forged balances or theft of funds. Recommended starting point (not yet
//     independently audited for Sur's use case — see sur-zether-confidential-transfers-proposal.md,
//     section 2, for the full evaluation): https://github.com/Consensys/anonymous-zether
//     (client-side library counterpart: https://github.com/kaleido-io/anonymous-zether-client).
//     ⚠️ Do not confuse this with github.com/ZetherOrg/go-zether, an unrelated PoW blockchain
//     that happens to share the "Zether" name.
//   - This file has NEVER been audited, tested against a live network, or reviewed by a
//     cryptography specialist. Do not deploy it — on Sur mainnet, testnet, or anywhere else
//     handling real value — before completing the phased plan in the proposal document
//     (reference-implementation selection → curve/precompile compatibility check → independent
//     security audit → deployment as an ordinary reference dApp).
// ============================================================================

/// @notice ILLUSTRATIVE interface for a Zether-style zero-knowledge proof verifier.
/// @dev The exact parameter shapes here are a reasonable approximation of what a Σ-Bullets
///      transfer/burn proof needs to check (sender's current encrypted balance, both parties'
///      public keys, the encrypted transfer deltas, and the proof bytes) — but they are NOT
///      guaranteed to match any specific real implementation byte-for-byte. Whoever forks a
///      real, audited Zether verifier MUST adjust this interface (and the call sites in
///      SurZether below) to match that implementation's actual proof structure exactly.
interface IZetherVerifier {
    /// @dev Verifies that a confidential transfer is well-formed: the sender's balance after
    ///      subtracting the encrypted amount remains non-negative, the same amount is added to
    ///      the receiver, and no value was created or destroyed — all without revealing the
    ///      amount itself. Parameters are grouped into structs (rather than flat uint256
    ///      arrays) specifically to keep EVM stack usage low enough to compile without
    ///      `viaIR` — see sur-contracts-deploy-notes.md for why this project avoids `viaIR`.
    function verifyTransfer(
        SurZetherTypes.Ciphertext memory senderBalance,
        SurZetherTypes.PubKey memory senderPubKey,
        SurZetherTypes.PubKey memory receiverPubKey,
        SurZetherTypes.Ciphertext memory deltaFrom,
        SurZetherTypes.Ciphertext memory deltaTo,
        bytes memory proof
    ) external view returns (bool);

    /// @dev Verifies that a burn (confidential balance -> plain Suren) of exactly `amount` is
    ///      valid against the account's current encrypted balance, without revealing anything
    ///      about the account's balance beyond the fact that it covers `amount`.
    function verifyBurn(
        SurZetherTypes.PubKey memory pubKey,
        SurZetherTypes.Ciphertext memory balance,
        uint256 amount,
        bytes memory proof
    ) external view returns (bool);
}

/// @dev Shared struct definitions, kept in their own library so both `SurZether` and any
///      `IZetherVerifier` implementation reference the exact same types.
library SurZetherTypes {
    struct Ciphertext {
        uint256 cx;
        uint256 cy;
        uint256 dx;
        uint256 dy;
    }

    struct PubKey {
        uint256 x;
        uint256 y;
    }
}

contract SurZether {
    // ------------------------------------------------------------------
    // BN254 (alt_bn128) curve constants — this is the curve Ethereum's standard ecAdd/ecMul
    // precompiles (addresses 0x06 / 0x07) operate on. See the proposal document, section 5,
    // for the open question of whether the chosen reference Zether implementation's proof
    // system is compatible with this specific curve, or needs adaptation.
    // ------------------------------------------------------------------
    uint256 internal constant GX = 1;
    uint256 internal constant GY = 2;
    uint256 internal constant FIELD_MODULUS =
        21888242871839275222246405745257275088696311157297823662689037894645226208583;

    struct Account {
        uint256 pubKeyX;
        uint256 pubKeyY;
        bool registered;
    }

    /// @dev Accounts are keyed by a hash of their Zether public key — deliberately NOT by
    ///      Ethereum address, since a single Ethereum address may want multiple independent
    ///      confidential accounts, and the Zether public key is a separate elliptic-curve key
    ///      pair the client manages (see the proposal document, section 6).
    mapping(bytes32 => Account) public accounts;
    mapping(bytes32 => SurZetherTypes.Ciphertext) public balances;

    IZetherVerifier public immutable verifier;

    event Registered(bytes32 indexed accountKey);
    event Funded(bytes32 indexed accountKey, uint256 amount);
    event Transferred(bytes32 indexed fromKey, bytes32 indexed toKey);
    event Burned(bytes32 indexed accountKey, uint256 amount);

    constructor(address _verifier) {
        require(_verifier != address(0), "SurZether: zero verifier address");
        verifier = IZetherVerifier(_verifier);
    }

    // ------------------------------------------------------------------
    // Registration — associates a Zether public key (an EC point, managed client-side) with
    // an on-chain confidential account. Anyone may register any number of accounts.
    // ------------------------------------------------------------------
    function register(uint256 pubKeyX, uint256 pubKeyY) external {
        bytes32 key = _accountKey(pubKeyX, pubKeyY);
        require(!accounts[key].registered, "SurZether: already registered");
        accounts[key] = Account({pubKeyX: pubKeyX, pubKeyY: pubKeyY, registered: true});
        emit Registered(key);
    }

    // ------------------------------------------------------------------
    // Funding — converts plain (public) Suren into an initial encrypted balance entry.
    // ⚠️ The funded AMOUNT is intentionally PUBLIC here — this matches Zether's original
    // design. Confidentiality only applies to `transfer` calls that happen afterward; the
    // deposit itself is as visible as any normal transaction.
    // ------------------------------------------------------------------
    function fund(bytes32 accountKey) external payable {
        require(accounts[accountKey].registered, "SurZether: account not registered");
        require(msg.value > 0, "SurZether: zero-value funding");

        (uint256 mx, uint256 my) = _ecMul(GX, GY, msg.value);
        SurZetherTypes.Ciphertext storage bal = balances[accountKey];
        (bal.dx, bal.dy) = _ecAdd(bal.dx, bal.dy, mx, my);
        // The C-component is unaffected: a "plaintext" contribution is an ElGamal ciphertext
        // with blinding factor r = 0, i.e. C = 0*G = the point at infinity, which ecAdd leaves
        // the existing C-component unchanged when added to it.

        emit Funded(accountKey, msg.value);
    }

    // ------------------------------------------------------------------
    // Confidential transfer — the core operation. See the top-of-file warning: `proof`
    // verification is entirely delegated to `verifier`, which MUST be an audited, real Zether
    // verifier before this function is ever used with real value.
    // ------------------------------------------------------------------
    function transfer(
        bytes32 fromKey,
        bytes32 toKey,
        SurZetherTypes.Ciphertext calldata deltaFrom, // encryption of -amount, sender's key
        SurZetherTypes.Ciphertext calldata deltaTo,   // encryption of +amount, receiver's key
        bytes calldata proof
    ) external {
        require(accounts[fromKey].registered, "SurZether: sender not registered");
        require(accounts[toKey].registered, "SurZether: receiver not registered");
        require(fromKey != toKey, "SurZether: self-transfer not allowed");

        bool ok = _checkTransferProof(fromKey, toKey, deltaFrom, deltaTo, proof);
        require(ok, "SurZether: invalid transfer proof");

        _applyTransfer(fromKey, toKey, deltaFrom, deltaTo);

        emit Transferred(fromKey, toKey);
    }

    /// @dev Split out of `transfer` purely to keep EVM stack usage low enough to compile
    ///      without `viaIR` (see the note on IZetherVerifier above) — behavior is unchanged.
    function _checkTransferProof(
        bytes32 fromKey,
        bytes32 toKey,
        SurZetherTypes.Ciphertext calldata deltaFrom,
        SurZetherTypes.Ciphertext calldata deltaTo,
        bytes calldata proof
    ) private view returns (bool) {
        Account storage sender = accounts[fromKey];
        Account storage receiver = accounts[toKey];

        return verifier.verifyTransfer(
            balances[fromKey],
            SurZetherTypes.PubKey({x: sender.pubKeyX, y: sender.pubKeyY}),
            SurZetherTypes.PubKey({x: receiver.pubKeyX, y: receiver.pubKeyY}),
            deltaFrom,
            deltaTo,
            proof
        );
    }

    /// @dev Split out of `transfer` for the same stack-depth reason as `_checkTransferProof`.
    function _applyTransfer(
        bytes32 fromKey,
        bytes32 toKey,
        SurZetherTypes.Ciphertext calldata deltaFrom,
        SurZetherTypes.Ciphertext calldata deltaTo
    ) private {
        SurZetherTypes.Ciphertext storage senderBalance = balances[fromKey];
        (senderBalance.cx, senderBalance.cy) =
            _ecAdd(senderBalance.cx, senderBalance.cy, deltaFrom.cx, deltaFrom.cy);
        (senderBalance.dx, senderBalance.dy) =
            _ecAdd(senderBalance.dx, senderBalance.dy, deltaFrom.dx, deltaFrom.dy);

        SurZetherTypes.Ciphertext storage receiverBalance = balances[toKey];
        (receiverBalance.cx, receiverBalance.cy) =
            _ecAdd(receiverBalance.cx, receiverBalance.cy, deltaTo.cx, deltaTo.cy);
        (receiverBalance.dx, receiverBalance.dy) =
            _ecAdd(receiverBalance.dx, receiverBalance.dy, deltaTo.dx, deltaTo.dy);
    }

    // ------------------------------------------------------------------
    // Burn — converts an encrypted balance back into plain, withdrawable Suren. The withdrawn
    // AMOUNT becomes public at this point (inherent to leaving the confidential system), but
    // the account's remaining encrypted balance stays hidden.
    // ------------------------------------------------------------------
    function burn(bytes32 accountKey, uint256 amount, bytes calldata proof) external {
        require(accounts[accountKey].registered, "SurZether: account not registered");
        require(amount > 0, "SurZether: zero-value burn");
        require(address(this).balance >= amount, "SurZether: insufficient contract balance");

        bool ok = _checkBurnProof(accountKey, amount, proof);
        require(ok, "SurZether: invalid burn proof");

        SurZetherTypes.Ciphertext storage bal = balances[accountKey];
        (uint256 mx, uint256 my) = _ecMul(GX, GY, amount);
        (bal.dx, bal.dy) = _ecAdd(bal.dx, bal.dy, mx, _negateY(my));

        (bool sent, ) = msg.sender.call{value: amount}("");
        require(sent, "SurZether: Suren withdrawal failed");

        emit Burned(accountKey, amount);
    }

    /// @dev Split out of `burn` for the same stack-depth reason as `_checkTransferProof`.
    function _checkBurnProof(bytes32 accountKey, uint256 amount, bytes calldata proof)
        private
        view
        returns (bool)
    {
        Account storage acc = accounts[accountKey];
        return verifier.verifyBurn(
            SurZetherTypes.PubKey({x: acc.pubKeyX, y: acc.pubKeyY}),
            balances[accountKey],
            amount,
            proof
        );
    }

    // ------------------------------------------------------------------
    // Internal helpers — elliptic-curve arithmetic and account keying.
    // ------------------------------------------------------------------

    function _accountKey(uint256 x, uint256 y) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(x, y));
    }

    function _negateY(uint256 y) internal pure returns (uint256) {
        return FIELD_MODULUS - (y % FIELD_MODULUS);
    }

    /// @dev Calls Ethereum's standard ecAdd precompile (address 0x06) — present on every
    ///      standard EVM client, including Besu, with no client-side modification required.
    function _ecAdd(uint256 x1, uint256 y1, uint256 x2, uint256 y2)
        internal
        view
        returns (uint256 x3, uint256 y3)
    {
        bool success;
        assembly {
            let input := mload(0x40)
            mstore(input, x1)
            mstore(add(input, 0x20), y1)
            mstore(add(input, 0x40), x2)
            mstore(add(input, 0x60), y2)
            success := staticcall(gas(), 0x06, input, 0x80, input, 0x40)
            x3 := mload(input)
            y3 := mload(add(input, 0x20))
        }
        require(success, "SurZether: ecAdd precompile call failed");
    }

    /// @dev Calls Ethereum's standard ecMul precompile (address 0x07) — present on every
    ///      standard EVM client, including Besu, with no client-side modification required.
    function _ecMul(uint256 x1, uint256 y1, uint256 scalar)
        internal
        view
        returns (uint256 x2, uint256 y2)
    {
        bool success;
        assembly {
            let input := mload(0x40)
            mstore(input, x1)
            mstore(add(input, 0x20), y1)
            mstore(add(input, 0x40), scalar)
            success := staticcall(gas(), 0x07, input, 0x60, input, 0x40)
            x2 := mload(input)
            y2 := mload(add(input, 0x20))
        }
        require(success, "SurZether: ecMul precompile call failed");
    }
}

contracts-baseline/ServiceStaking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @title ServiceStaking
/// @notice A generic, reusable "stake for service access" ledger — see sur-tokenomics.md
///         section 10 for the full decision table this implements. This is a first-draft
///         skeleton (like SurZether.sol), not a hardened, audited contract — it is explicitly
///         flagged as still needing design review before any real deployment.
///
///         PURPOSE: several planned dapps/services (naming, timestamping, credential issuance,
///         business registry, Zether higher limits, a reputation layer) each need users or
///         issuers to lock some Suren for access — but with DIFFERENT rules per service:
///           - Naming: MANDATORY, held for as long as the name is kept, instant release on exit.
///           - Timestamping: OPTIONAL perk (higher daily quota), instant release on exit.
///           - Credential issuance: MANDATORY (on the issuer, not the credential recipient),
///             90-day cooldown on exit (to allow review of credentials already issued).
///           - Business registry: MANDATORY (on the registrant), 90-day cooldown on exit (same
///             reasoning — review window for entries already made).
///           - Zether confidential-tx higher limit: OPTIONAL perk, 7-day cooldown on exit
///             (shorter than the above two because this is about transaction limits, not
///             identity/registry entries that need a review window).
///           - Reputation/credit layer: the stake AMOUNT ITSELF is the score (not a binary
///             gate) — with a minimum 90-day mandatory lock before ANY withdrawal can even be
///             requested, so the score reflects sustained commitment, not a same-day stake-and-
///             unstake to temporarily inflate it.
///
///         DESIGN CHOICE — one generic contract, not six bespoke ones: every service above
///         reduces to the same primitive ("lock N Suren for service X, release after cooldown
///         Y"), just with different cooldown values and one special-cased minimum-lock rule for
///         Reputation. Rather than reimplementing this lock/release pattern six times (or
///         copy-pasting the pattern already proven in ValidatorsRegistry's collateral handling),
///         this contract implements it once, parameterized by a ServiceId enum. Each consuming
///         contract (a future NamingService, CredentialRegistry, etc.) is expected to call
///         `hasMinimumStake()` or `stakeOf()` as a view check before granting its own service —
///         this contract does not know or enforce which services are "mandatory"; that
///         enforcement lives in each consuming contract's own logic.
///
///         🔶 OPEN DESIGN QUESTIONS (not yet decided, listed here rather than guessed at):
///           - Exact minimum stake AMOUNTS per service (this contract only enforces cooldowns
///             and the Reputation minimum-lock DURATION — not minimum stake sizes; those are a
///             separate, still-open economic decision, likely to differ per service and
///             possibly to need governance rather than being hardcoded here).
///           - Whether withdrawalCooldown per service should become governable later (currently
///             hardcoded in the constructor, matching this project's general pattern of
///             "ship with a reasonable hardcoded default, revisit via full validator vote if it
///             turns out to need changing" — see e.g. slashBps in ValidatorsRegistry).
///           - Whether this contract itself should be genesis-injected (a seventh structural
///             address) or deployed normally like SurenSale. This draft assumes the SurenSale
///             pattern (normal deploy, real constructor, no genesis `alloc` entry) since it is
///             an optional ecosystem convenience, not core network infrastructure.
contract ServiceStaking {
    enum ServiceId {
        Naming,           // mandatory, no fixed term, instant withdrawal
        Timestamping,     // optional perk, instant withdrawal
        CredentialIssuer, // mandatory (on issuer), 90-day withdrawal cooldown
        BusinessRegistry, // mandatory (on registrant), 90-day withdrawal cooldown
        ZetherLimit,      // optional perk, 7-day withdrawal cooldown
        Reputation        // stake amount = score; 90-day MINIMUM LOCK before any withdrawal request
    }

    struct Stake {
        uint256 amount;
        uint256 stakedAt;              // first-staked timestamp — used only by Reputation's minimum lock
        uint256 withdrawalRequestedAt; // 0 = no pending request; only used when cooldown > 0
    }

    /// @notice Seconds that must elapse between requesting withdrawal and actually withdrawing,
    ///         per service. Zero means "no request step needed — withdraw() works immediately."
    mapping(ServiceId => uint256) public withdrawalCooldown;

    /// @notice user => service => their current stake info.
    mapping(address => mapping(ServiceId => Stake)) public stakes;

    event Staked(address indexed user, ServiceId indexed service, uint256 amount, uint256 newTotal);
    event WithdrawalRequested(address indexed user, ServiceId indexed service, uint256 availableAt);
    event Withdrawn(address indexed user, ServiceId indexed service, uint256 amount);

    constructor() {
        withdrawalCooldown[ServiceId.Naming] = 0;
        withdrawalCooldown[ServiceId.Timestamping] = 0;
        withdrawalCooldown[ServiceId.CredentialIssuer] = 90 days;
        withdrawalCooldown[ServiceId.BusinessRegistry] = 90 days;
        withdrawalCooldown[ServiceId.ZetherLimit] = 7 days;
        withdrawalCooldown[ServiceId.Reputation] = 0; // no cooldown AFTER request — the 90-day
        // rule for Reputation is a minimum lock BEFORE a request is even allowed (see
        // requestWithdrawal/withdraw below), which is a different mechanism than the other
        // services' "request now, wait, then withdraw" cooldown.
    }

    /// @notice Lock more Suren for a given service. Repeatable — additional stakes simply add
    ///         to the existing amount. Staking more also cancels any pending withdrawal request
    ///         for that service (you can't be simultaneously "adding stake" and "exiting").
    function stake(ServiceId service) external payable {
        require(msg.value > 0, "ServiceStaking: zero stake amount");

        Stake storage s = stakes[msg.sender][service];
        // ✅ FIXED (critical exploit found in review): previously `stakedAt` was only set on
        // the FIRST stake (when s.amount == 0), meaning a top-up after the original 90-day
        // Reputation lock had already elapsed did NOT reset the clock — so a user could stake a
        // trivial amount, wait 90 days, then top up with a large amount and withdraw it all
        // immediately, since the lock check only ever looked at the original (tiny) stake's
        // timestamp. Fix: for Reputation specifically, EVERY stake() call (top-up or first)
        // resets stakedAt to now, restarting the 90-day lock for the full new balance — since
        // Reputation's whole design intent is "the weight/lock reflects your CURRENT staked
        // amount," a top-up must not inherit an already-expired lock from a much smaller
        // earlier stake. Other services don't use stakedAt for anything (their cooldown is
        // computed from withdrawalRequestedAt instead), so this change is a no-op for them.
        if (service == ServiceId.Reputation) {
            s.stakedAt = block.timestamp;
        } else if (s.amount == 0) {
            s.stakedAt = block.timestamp;
        }
        s.amount += msg.value;
        s.withdrawalRequestedAt = 0;

        emit Staked(msg.sender, service, msg.value, s.amount);
    }

    /// @notice Required before withdraw() for any service with a non-zero cooldown
    ///         (CredentialIssuer, BusinessRegistry, ZetherLimit). Not needed — and reverts —
    ///         for zero-cooldown services (Naming, Timestamping), which withdraw directly.
    ///         For Reputation, this additionally enforces the 90-day minimum lock.
    function requestWithdrawal(ServiceId service) external {
        Stake storage s = stakes[msg.sender][service];
        require(s.amount > 0, "ServiceStaking: no stake to withdraw");
        require(withdrawalCooldown[service] > 0, "ServiceStaking: this service has no cooldown, call withdraw() directly");

        s.withdrawalRequestedAt = block.timestamp;
        emit WithdrawalRequested(msg.sender, service, block.timestamp + withdrawalCooldown[service]);
    }

    /// @notice Withdraws the caller's full stake for a service. Behavior depends on the
    ///         service's cooldown:
    ///           - Zero cooldown (Naming, Timestamping, Reputation): works immediately, no
    ///             prior requestWithdrawal() call needed — EXCEPT Reputation, which still
    ///             enforces its own 90-day minimum lock from the original stake time,
    ///             independent of the (zero) cooldown mechanism.
    ///           - Non-zero cooldown (CredentialIssuer, BusinessRegistry, ZetherLimit):
    ///             requires a prior requestWithdrawal() call and that its cooldown has elapsed.
    function withdraw(ServiceId service) external {
        Stake storage s = stakes[msg.sender][service];
        require(s.amount > 0, "ServiceStaking: no stake");

        uint256 cooldown = withdrawalCooldown[service];
        if (cooldown > 0) {
            require(s.withdrawalRequestedAt > 0, "ServiceStaking: call requestWithdrawal first");
            require(block.timestamp >= s.withdrawalRequestedAt + cooldown, "ServiceStaking: cooldown not elapsed");
        }

        if (service == ServiceId.Reputation) {
            require(block.timestamp >= s.stakedAt + 90 days, "ServiceStaking: reputation stake still in its 90-day minimum lock");
        }

        uint256 amount = s.amount;
        s.amount = 0;
        s.stakedAt = 0;
        s.withdrawalRequestedAt = 0;

        emit Withdrawn(msg.sender, service, amount);
        (bool success, ) = msg.sender.call{value: amount}("");
        require(success, "ServiceStaking: transfer failed");
    }

    // ------------------------------------------------------------------
    // View helpers — for consuming contracts (NamingService, CredentialRegistry, etc.) and
    // off-chain dashboards.
    // ------------------------------------------------------------------

    function stakeOf(address user, ServiceId service) external view returns (uint256) {
        return stakes[user][service].amount;
    }

    /// @notice Convenience check for a consuming contract's own "is this address allowed to
    ///         use my service" gate — e.g. `require(serviceStaking.hasMinimumStake(msg.sender,
    ///         ServiceId.BusinessRegistry, MIN_REGISTRANT_STAKE), ...)`. This contract does not
    ///         define what `minAmount` should be for any service — that is each consuming
    ///         contract's own decision (see the open design questions in the header comment).
    function hasMinimumStake(address user, ServiceId service, uint256 minAmount) external view returns (bool) {
        return stakes[user][service].amount >= minAmount;
    }
}

contracts-baseline/SurAddresses.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @title SurAddresses
/// @notice Fixed, genesis-assigned addresses for the SUR network's six structural contracts.
///         All six are deployed directly in the genesis block's `alloc` section (bytecode +
///         storage injected directly, not via a regular deployment transaction — see
///         "sur-contracts-deploy-notes.md" for the exact recipe). Because every one of these
///         addresses is therefore known and fixed before any contract's constructor logic is
///         even simulated, each contract can hardcode references to the others as constants
///         instead of needing a runtime "wire()" step after deployment (the previous approach,
///         now retired).
///
///         Do not change these values after genesis has been generated — they are baked into
///         every other contract's bytecode as constants, not stored in mutable state.
library SurAddresses {
    /// @dev FoundationDAO — SUR Foundation governance (15 members)
    address internal constant FOUNDATION_DAO = 0x1111111111111111111111111111111111111111;

    /// @dev BlockRewardDistributor — receives block reward + fees as miningbeneficiary,
    ///      periodically pays out validators + ValidatorsTreasury
    address internal constant BLOCK_REWARD_DISTRIBUTOR = 0x2222222222222222222222222222222222222222;

    /// @dev ValidatorsRegistry — source of truth for consensus (getValidators()) and payment
    ///      eligibility (isValidator()). This is the address that must also be set as
    ///      qbft.validatorcontractaddress in genesis.json.
    address internal constant VALIDATORS_REGISTRY = 0x3333333333333333333333333333333333333333;

    /// @dev ValidatorsBoard — small elected/recallable board with narrow delegated powers
    address internal constant VALIDATORS_BOARD = 0x4444444444444444444444444444444444444444;

    /// @dev ValidatorsTreasury — holds and spends the validators' share of the reward pool
    ///      (the remainder after Foundation's fixed 15% and validators' governable direct
    ///      share — no longer a fixed 50%; see BlockRewardDistributor.validatorDirectShareBps)
    address internal constant VALIDATORS_TREASURY = 0x5555555555555555555555555555555555555555;

    /// @dev IdentityRegistry — the sixth structural contract (added in a later revision). The
    ///      single source of truth for self-attested identity (name/person type) and
    ///      verification status (mobile/Telegram/full KYC) for **all network users**, not just
    ///      validators — which is why it is kept independent from ValidatorsRegistry.
    address internal constant IDENTITY_REGISTRY = 0x6666666666666666666666666666666666666666;

    // ------------------------------------------------------------------
    // Operational oracle addresses — unlike the six structural contract addresses above, these
    // are NOT immutable constants baked into every consumer forever: each contract still stores
    // its own oracle address in ordinary (mutable) state, initialized from here, and can later
    // rotate it via its own governance path (ValidatorsBoard for distributionOracle/verifier,
    // FoundationDAO for identityOracle/paymentOracle). Centralizing the *initial* value here,
    // in one file, means updating an oracle before genesis/deployment only requires editing one
    // line instead of hunting through four separate contract files. All four are checksummed
    // per EIP-55.
    // ------------------------------------------------------------------

    /// @dev Initial distributionOracle for BlockRewardDistributor.sol.
    address internal constant DISTRIBUTION_ORACLE = 0xbCBAc7d286eA11EC57fb4e0f5D16d960D6d202b6;

    /// @dev Initial verifier for ValidatorsRegistry.sol.
    address internal constant VERIFIER = 0x1A5E86f3333291B3332C0f9Eddb04269940566bc;

    /// @dev Initial identityOracle for IdentityRegistry.sol.
    address internal constant IDENTITY_ORACLE = 0xbE7e65512Eada6F4c6a9DEDDf2eFb75547A065e9;

